const input = $input.first()?.json || {};

function text(value, fallback = '') {
  const result = String(value ?? '').replace(/\r\n/g, '\n').replace(/\r/g, '\n').trim();
  return result || fallback;
}
function list(value) {
  if (Array.isArray(value)) return value;
  if (!value) return [];
  if (typeof value === 'object') return [value];
  try {
    const parsed = JSON.parse(String(value));
    return Array.isArray(parsed) ? parsed : [];
  } catch (error) {
    return [];
  }
}

const userId = text(input.userId || input.memoryUserId);
const memoryTenantId = text(input.memoryTenantId || input.tenantId);
const tenantId = text(input.tenantId || memoryTenantId);
if (!tenantId || !memoryTenantId) {
  throw new Error('Resolution queue requires tenantId and memoryTenantId.');
}
if (tenantId !== memoryTenantId) {
  throw new Error('Resolution queue requires tenantId to equal memoryTenantId.');
}
const memoryUserId = text(input.memoryUserId || userId);
const telegramUserId = text(input.telegramUserId);
const chatId = text(input.chatId || input.telegramChatId || input.telegramUserId);
const qdrantCollection = text(input.qdrantCollection);
if (!userId || !memoryUserId || !/^\d+$/.test(telegramUserId) || Number(telegramUserId)<=0 || !chatId || !qdrantCollection) {
  throw new Error('Resolution queue identity requires user, Telegram chat, and Qdrant collection.');
}

const questions = list(input.questions || input.resolutionQuestions)
  .filter(value => value && typeof value === 'object');

return [{ json: {
  ...input,
  userId,
  memoryUserId,
  tenantId,
  memoryTenantId,
  telegramActorId,
  telegramUserId,
  chatId,
  messageId: text(input.messageId || input.sourceMessageId),
  messageDateIso: text(input.messageDateIso),
  qdrantCollection,
  uploadId: text(input.uploadId),
  sourceTitle: text(input.sourceTitle),
  questionTableName: 'Chelsea Resolution Questions',
  questions,
  questionCount: questions.length,
  queueSchemaVersion: 'chelsea_resolution_questions_v2_0'
} }];

const runtime = $('Code | Normalize Resolution Queue Request | InputModule').first().json || {};
const questions = Array.isArray(runtime.questions) ? runtime.questions : [];

function text(value, fallback = '') {
  const result = String(value ?? '').replace(/\r\n/g, '\n').replace(/\r/g, '\n').trim();
  return result || fallback;
}
function arr(value) {
  if (Array.isArray(value)) return value;
  if (!value) return [];
  try { const parsed = JSON.parse(String(value)); return Array.isArray(parsed) ? parsed : []; }
  catch (error) { return []; }
}
function json(value, fallback) {
  try { return JSON.stringify(value ?? fallback); }
  catch (error) { return JSON.stringify(fallback); }
}
function unique(values, limit = 50) {
  const out = [];
  const seen = new Set();
  for (const value of values || []) {
    const key = text(value);
    if (!key || seen.has(key)) continue;
    seen.add(key);
    out.push(key);
    if (out.length >= limit) break;
  }
  return out;
}
function hash(value) {
  const source = String(value ?? '').normalize('NFKC');
  let a = 0x811c9dc5;
  let b = 0x9e3779b9;
  for (let index = 0; index < source.length; index += 1) {
    const code = source.charCodeAt(index);
    a ^= code;
    a = Math.imul(a, 0x01000193) >>> 0;
    b ^= code + index;
    b = Math.imul(b, 0x85ebca6b) >>> 0;
  }
  return a.toString(16).padStart(8, '0') + b.toString(16).padStart(8, '0');
}
function candidateRows(question) {
  return arr(question.candidates || question.personResolutionCandidates)
    .map(candidate => {
      if (!candidate || typeof candidate !== 'object') return null;
      const ref = text(candidate.personId || candidate.ref || candidate.id);
      if (!ref) return null;
      return {
        ref,
        label: text(candidate.displayName || candidate.canonicalName || candidate.title || ref, ref).slice(0, 60),
        personId: ref,
        qdrantPointId: text(candidate.qdrantPointId),
        disambiguationLabel: text(candidate.disambiguationLabel),
        confidence: Number(candidate.resolutionScore || candidate.confidence || 0)
      };
    })
    .filter(Boolean)
    .slice(0, 6);
}

if (!questions.length) {
  return [{ json: { ...runtime, hasQuestion: false, status: 'no_questions' } }];
}

return questions.map((question, index) => {
  const identityChecks = [
    ['tenantId', question.tenantId, runtime.tenantId],
    ['memoryTenantId', question.memoryTenantId, runtime.memoryTenantId],
    ['userId', question.userId, runtime.userId],
    ['memoryUserId', question.memoryUserId, runtime.memoryUserId],
    ['telegramUserId', question.telegramUserId, runtime.telegramUserId],
    ['chatId', question.chatId || question.telegramChatId, runtime.chatId],
    ['qdrantCollection', question.qdrantCollection, runtime.qdrantCollection],
    ['sourceMessageId', question.sourceMessageId || question.messageId, runtime.messageId]
  ];
  for (const [field, supplied, expected] of identityChecks) {
    if (text(supplied) && text(supplied) !== text(expected)) {
      throw new Error(`Resolution question ${index} ${field} does not match the queue runtime identity.`);
    }
  }
  const pointType = text(question.pointType || question.knowledgeType || question.questionType).toLowerCase();
  const questionType = pointType === 'memory_conflict'
    ? 'memory_conflict'
    : ['person_resolution', 'person_resolution_question'].includes(pointType)
      ? 'person_resolution'
      : '';
  if (!questionType) {
    throw new Error(`Unsupported resolution question type at index ${index}.`);
  }

  const questionId = text(
    question.questionId || question.resolutionQuestionId || question.knowledgeId,
    `resolution_${hash(`${runtime.memoryTenantId}|${runtime.messageId}|${index}`)}`
  );
  const callbackQuestionKey = hash(`${runtime.memoryTenantId}|${questionId}`);
  const questionRowKey = `resolution_row_${callbackQuestionKey}`;
  const rowInstanceId = `resolution_instance_${callbackQuestionKey}`;
  // Reuse the full 64-bit callback key. Ten hex digits become collision-prone
  // in a long-lived global multi-tenant table; sixteen remain short enough for
  // a human-visible Telegram correlation token.
  const questionToken = `CQ-${callbackQuestionKey.toUpperCase()}`;
  const candidates = candidateRows(question);
  const existingValue = text(question.existingValue);
  const incomingValue = text(question.incomingValue);
  const allowCreateNewPerson = question.allowCreateNewPerson !== false;
  const options = [];

  if (questionType === 'memory_conflict') {
    options.push({ ref: 'keep_existing', label: 'Оставить прежнее', value: existingValue });
    options.push({ ref: 'accept_incoming', label: 'Принять новое', value: incomingValue });
  } else {
    for (const candidate of candidates) options.push({ ref: candidate.ref, label: candidate.label, personId: candidate.personId });
    if (allowCreateNewPerson) options.push({ ref: 'create_new', label: 'Это новый человек' });
    options.push({ ref: 'reject', label: 'Ни один вариант' });
  }

  const callbackOptions = options.slice(0, 8).map((option, optionIndex) => ({
    ...option,
    index: optionIndex,
    optionToken: hash(`${runtime.memoryTenantId}|${questionId}|${option.ref}`),
    callbackData: `chelsea_res:${callbackQuestionKey}:${hash(`${runtime.memoryTenantId}|${questionId}|${option.ref}`)}`
  }));
  const questionText = text(
    question.questionText || question.question || question.content || question.title,
    questionType === 'memory_conflict'
      ? 'Уточните, какое значение сейчас верно.'
      : 'Уточните, о каком человеке идёт речь.'
  ).slice(0, 3500);
  const provisionalPersonId = text(question.provisionalPersonId || question.context?.provisionalPersonId);
  const qdrantQuestionPointId = text(question.qdrantQuestionPointId || question.qdrantPointId);
  if (!qdrantQuestionPointId) {
    throw new Error(`Resolution question ${questionId} has no qdrantQuestionPointId.`);
  }

  return { json: {
    hasQuestion: true,
    questionRowKey,
    rowInstanceId,
    questionTableName: runtime.questionTableName,
    questionId,
    tenantId: runtime.tenantId,
    memoryTenantId: runtime.memoryTenantId,
    userId: runtime.userId,
    memoryUserId: runtime.memoryUserId,
    telegramUserId: runtime.telegramUserId,
    chatId: runtime.chatId,
    sourceMessageId: runtime.messageId,
    sourceMessageDateIso: text(question.messageDateIso, runtime.messageDateIso),
    uploadId: text(question.uploadId, runtime.uploadId),
    sourceTitle: text(question.sourceTitle, runtime.sourceTitle),
    qdrantCollection: runtime.qdrantCollection,
    questionType,
    status: 'pending',
    priority: Math.max(1, Math.min(Number(question.priority || (questionType === 'memory_conflict' ? 9 : 6)), 10)),
    questionText,
    mention: text(question.mention),
    subjectName: text(question.subjectName),
    relatedKnowledgeId: text(question.relatedKnowledgeId || question.stableKnowledgeId),
    relatedKnowledgeTitle: text(question.relatedKnowledgeTitle || question.predicateLabel),
    qdrantQuestionPointId,
    stableKnowledgeId: text(question.stableKnowledgeId),
    stableQdrantPointId: text(question.stableQdrantPointId),
    existingValue,
    incomingValue,
    plausibleHeadRefsJson: json(unique(arr(question.plausibleHeadRefs), 20), []),
    candidatesJson: json(candidates, []),
    candidateRefsJson: json(candidates.map(candidate => candidate.ref), []),
    allowCreateNewPerson,
    provisionalPersonId,
    resolutionReason: text(question.resolutionReason || question.reason),
    confidence: Number(question.confidence || question.personResolutionConfidence || 0),
    resolutionPolicy: text(question.resolutionPolicy),
    callbackQuestionKey,
    questionToken,
    callbackOptionsJson: json(callbackOptions, []),
    correlationKey: '',
    dispatchLeaseOwner: '',
    dispatchLeaseUntil: '',
    dispatchAttemptCount: 0,
    telegramQuestionMessageId: '',
    askedAt: '',
    askedExpiresAt: '',
    stateChangedAt: new Date().toISOString(),
    answerMessageId: '',
    answerText: '',
    selectedRef: '',
    answeredAt: '',
    answerIdempotencyKey: '',
    answerClaimLeaseOwner: '',
    answerClaimLeaseUntil: '',
    answerAttemptCount: 0,
    lastAnswerAttemptMessageId: '',
    jobId: '',
    lastAcceptedJobId: '',
    lastAcceptedAnswerMessageId: '',
    lastAcceptedAnswerText: '',
    lastAcceptedSelectedRef: '',
    lastAcceptedAnswerIdempotencyKey: '',
    lastAcceptedAt: '',
    appliedAt: '',
    selectedPersonId: '',
    resolutionResultJson: '',
    lastError: '',
    contextJson: json({
      relationToUser: question.relationToUser || '',
      sourceEvidence: question.sourceEvidence || question.evidence || '',
      tags: arr(question.tags),
      provisionalPersonId,
      stableKnowledgeId: text(question.stableKnowledgeId),
      stableQdrantPointId: text(question.stableQdrantPointId),
      existingValue,
      incomingValue,
      plausibleHeadRefs: unique(arr(question.plausibleHeadRefs), 20),
      payloadShape: text(question.payloadShape)
    }, {}),
    queueSchemaVersion: 'chelsea_resolution_questions_v2_0'
  } };
});

const incomingRows = $items('Code | Build Resolution Question Rows | QueueWrite').map(item => item.json || {});
const existingRows = $input.all().map(item => item.json || {}).filter(row => String(row.questionId || '').trim());

const terminal = new Set([
  'dispatching', 'asked', 'answer_claimed', 'answer_queued', 'applying',
  'resolved', 'needs_clarification', 'rejected', 'closed', 'deferred', 'failed_review'
]);
function text(value) { return String(value ?? '').trim(); }
function exactIdentity(incoming, existing) {
  for (const field of [
    'questionId', 'memoryTenantId', 'tenantId', 'questionType', 'qdrantQuestionPointId',
    'qdrantCollection', 'relatedKnowledgeId', 'stableKnowledgeId', 'stableQdrantPointId'
  ]) {
    if (text(incoming[field]) !== text(existing[field])) {
      throw new Error(`Existing resolution question changed immutable ${field}.`);
    }
  }
  if (text(existing.questionRowKey) && text(existing.questionRowKey) !== text(incoming.questionRowKey)) {
    throw new Error('Existing resolution question has another logical row key.');
  }
}
function merge(incoming, existing) {
  exactIdentity(incoming, existing);
  const currentStatus = text(existing.status).toLowerCase();
  if (terminal.has(currentStatus)) {
    return { ...incoming, ...existing, questionRowKey: incoming.questionRowKey,
      rowInstanceId: text(existing.rowInstanceId) || incoming.rowInstanceId,
      hasQuestion: true, duplicatePreserved: true };
  }
  return {
    ...incoming,
    rowInstanceId: text(existing.rowInstanceId) || incoming.rowInstanceId,
    correlationKey: existing.correlationKey || incoming.correlationKey,
    telegramQuestionMessageId: existing.telegramQuestionMessageId || '',
    askedAt: existing.askedAt || '',
    askedExpiresAt: existing.askedExpiresAt || '',
    stateChangedAt: existing.stateChangedAt || incoming.stateChangedAt,
    answerMessageId: existing.answerMessageId || '',
    answerText: existing.answerText || '',
    selectedRef: existing.selectedRef || '',
    answeredAt: existing.answeredAt || '',
    answerIdempotencyKey: existing.answerIdempotencyKey || '',
    answerClaimLeaseOwner: existing.answerClaimLeaseOwner || '',
    answerClaimLeaseUntil: existing.answerClaimLeaseUntil || '',
    answerAttemptCount: Number(existing.answerAttemptCount || 0),
    lastAnswerAttemptMessageId: existing.lastAnswerAttemptMessageId || '',
    jobId: existing.jobId || '',
    lastAcceptedJobId: existing.lastAcceptedJobId || '',
    lastAcceptedAnswerMessageId: existing.lastAcceptedAnswerMessageId || '',
    lastAcceptedAnswerText: existing.lastAcceptedAnswerText || '',
    lastAcceptedSelectedRef: existing.lastAcceptedSelectedRef || '',
    lastAcceptedAnswerIdempotencyKey: existing.lastAcceptedAnswerIdempotencyKey || '',
    lastAcceptedAt: existing.lastAcceptedAt || '',
    appliedAt: existing.appliedAt || '',
    selectedPersonId: existing.selectedPersonId || '',
    resolutionResultJson: existing.resolutionResultJson || '',
    lastError: existing.lastError || '',
    status: currentStatus || 'pending',
    duplicatePreserved: true
  };
}

return incomingRows.map(incoming => {
  const matches = existingRows.filter(existing =>
    text(existing.questionId) === text(incoming.questionId)
      && text(existing.memoryTenantId || existing.tenantId) === text(incoming.memoryTenantId));
  if (matches.length > 1) throw new Error(`Duplicate resolution question rows found for ${text(incoming.questionId)}.`);
  return { json: matches.length ? merge(incoming, matches[0]) : incoming };
});

const expectedRows = $items('Code | Preserve Existing Resolution State | QueueWrite').map(item => item.json || {});
const actualRows = $input.all().map(item => item.json || {}).filter(row => String(row.questionId || '').trim());
function text(value) { return String(value ?? '').trim(); }
function canonical(value) {
  if (value === null || typeof value !== 'object') return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`;
  return `{${Object.keys(value).sort().filter(key => value[key] !== undefined).map(key => `${JSON.stringify(key)}:${canonical(value[key])}`).join(',')}}`;
}

return expectedRows.map(expected => {
  const matches = actualRows.filter(actual => text(actual.questionRowKey) === text(expected.questionRowKey));
  if (matches.length !== 1) {
    throw new Error(`Resolution question upsert read-back cardinality is ${matches.length} for ${text(expected.questionId)}.`);
  }
  const actual = matches[0];
  for (const field of [
    'questionRowKey', 'rowInstanceId', 'questionId', 'tenantId', 'memoryTenantId',
    'questionType', 'qdrantQuestionPointId', 'qdrantCollection', 'status', 'callbackOptionsJson',
    'answerMessageId', 'answerText', 'selectedRef', 'jobId'
  ]) {
    if (canonical(actual[field]) !== canonical(expected[field])) {
      throw new Error(`Resolution question upsert read-back mismatch for ${field}.`);
    }
  }
  return { json: { ...expected, resolutionQuestionUpsertVerified: true } };
});

const rows = $input.all().map(item => item.json || {});
const queued = rows.filter(row => row.hasQuestion === true);
return [{ json: {
  status: queued.length ? 'queued' : 'no_questions',
  questionCount: queued.length,
  questionIds: queued.map(row => row.questionId).filter(Boolean),
  questionTypes: queued.reduce((out, row) => {
    const key = String(row.questionType || 'unknown');
    out[key] = (out[key] || 0) + 1;
    return out;
  }, {}),
  duplicatePreservedCount: queued.filter(row => row.duplicatePreserved === true).length,
  questionTableName: 'Chelsea Resolution Questions',
  queueSchemaVersion: 'chelsea_resolution_questions_v2_0',
  queuedAt: new Date().toISOString()
} }];

'use strict';
const input=$input.first()?.json||{};
const text=v=>String(v??'').normalize('NFKC').trim();
const username=v=>text(v).replace(/^@+/,'').toLowerCase();
const principalKey=text(input.principalKey);
const storageUsername=username(input.storageUsername||input.userId||input.memoryUserId);
const currentUsername=username(input.currentUsername||input.telegramUsername);
const telegramActorId=text(input.telegramActorId||input.telegramUserId);
if(!/^tgactor_[a-f0-9]{64}$/.test(principalKey))throw new Error('identity boundary: invalid principalKey');
if(!/^actor_[a-f0-9]{32}$/.test(storageUsername))throw new Error('identity boundary: invalid storageUsername');
if(!/^\d+$/.test(telegramActorId)||Number(telegramActorId)<=0)throw new Error('identity boundary: numeric Telegram actor required');
if(text(input.telegramActorId)&&text(input.telegramUserId)&&text(input.telegramActorId)!==text(input.telegramUserId))throw new Error('identity boundary: Telegram actor fields mismatch');
if(currentUsername&&!/^[a-z0-9_]{1,64}$/.test(currentUsername))throw new Error('identity boundary: invalid currentUsername');
const expected={userId:storageUsername,memoryUserId:storageUsername,tenantId:`tenant_${storageUsername}`,memoryTenantId:`tenant_${storageUsername}`,qdrantCollection:`kb_tenant_${storageUsername}`,soulId:`chelsea_soul_${storageUsername}`};
for(const [key,value] of Object.entries(expected)){if(text(input[key])!==value)throw new Error(`identity boundary: ${key} mismatch`);}
const schema=text(input.identitySchemaVersion);if(schema!=='chelsea_actor_identity_v3')throw new Error('identity boundary: schema mismatch');
if(input.identityAuthorityVerified!==true&&input.identityClaimsVerified!==true)throw new Error('identity boundary: PostgreSQL authority verification required');
return [{json:{...input,...expected,principalKey,storageUsername,currentUsername,telegramUsername:currentUsername,telegramActorId,telegramUserId:telegramActorId,identitySchemaVersion:schema,identityStatus:text(input.identityStatus)||'active',identityBoundaryVerified:true}}];
